using HMS.Infrastructure.Persistence.Entities.Security;
using Microsoft.EntityFrameworkCore;
namespace HMS.Infrastructure.Persistence.Context;
public sealed class HmsDbContext(DbContextOptions<HmsDbContext> options) : DbContext(options)
{
 internal DbSet<AppUser> AppUsers => Set<AppUser>(); internal DbSet<RefreshToken> RefreshTokens => Set<RefreshToken>(); internal DbSet<AccessToken> AccessTokens => Set<AccessToken>(); internal DbSet<LoginHistory> LoginHistories => Set<LoginHistory>(); internal DbSet<UserRole> UserRoles => Set<UserRole>(); internal DbSet<Role> Roles => Set<Role>(); internal DbSet<RolePermission> RolePermissions => Set<RolePermission>(); internal DbSet<Permission> Permissions => Set<Permission>();
 protected override void OnModelCreating(ModelBuilder m) { m.Entity<AppUser>(e=>{e.ToTable("AppUser","Security");e.HasKey(x=>x.UserId);e.HasIndex(x=>x.Username).IsUnique();e.HasIndex(x=>x.Email).IsUnique();e.Property(x=>x.Username).HasMaxLength(100);e.Property(x=>x.Email).HasMaxLength(320);e.Property(x=>x.Phone).HasMaxLength(30);e.Property(x=>x.PasswordHash).HasMaxLength(512);e.Property(x=>x.PasswordSalt).HasMaxLength(256);}); m.Entity<RefreshToken>(e=>{e.ToTable("RefreshToken","Security");e.HasKey(x=>x.RefreshTokenId);e.HasIndex(x=>x.TokenHash).IsUnique();});m.Entity<AccessToken>(e=>{e.ToTable("AccessToken","Security");e.HasKey(x=>x.AccessTokenId);});m.Entity<LoginHistory>(e=>{e.ToTable("LoginHistory","Security");e.HasKey(x=>x.LoginHistoryId);});m.Entity<UserRole>(e=>{e.ToTable("UserRole","Security");e.HasKey(x=>new{x.UserId,x.RoleId});});m.Entity<Role>(e=>{e.ToTable("Role","Security");e.HasKey(x=>x.RoleId);});m.Entity<RolePermission>(e=>{e.ToTable("RolePermission","Security");e.HasKey(x=>new{x.RoleId,x.PermissionId});});m.Entity<Permission>(e=>{e.ToTable("Permission","Security");e.HasKey(x=>x.PermissionId);}); }
}
